<div class="fd-dialog-product"><img :src="reviewTarget?.item.imageUrl" :alt="reviewTarget?.item.title"><div><h3 x-text="reviewTarget?.item.title"></h3><p x-text="reviewTarget?.item.variantTitle"></p><p>Your rating</p><div class="fd-dialog-stars">@for($star=1;$star<=5;$star++)<button type="button" @click="reviewRating={{ $star }};reviewErrors.rating=null" @mouseenter="reviewHoverRating={{ $star }}" @mouseleave="reviewHoverRating=0" :class="(reviewHoverRating||reviewRating)>={{ $star }}?'selected':''" aria-label="{{ $star }} star" x-text="(reviewHoverRating||reviewRating)>={{ $star }}?'★':'☆'">☆</button>@endfor</div><p class="fd-error" x-show="reviewErrors.rating" x-text="reviewErrors.rating"></p></div></div>
