<label>Add photos (optional)</label><input x-ref="reviewPhotosInput" type="file" accept="image/jpeg,image/png,image/webp" multiple @change="selectReviewPhotos($event)" hidden><div class="fd-dialog-photos"><button class="fd-dialog-upload" type="button" @click="$refs.reviewPhotosInput.click()">Upload photos<small>Up to 5 photos · 5 MB each</small></button><template x-for="(photo,index) in reviewPhotos" :key="photo.url"><div><img :src="photo.url" :alt="photo.file.name"><button type="button" @click="removeReviewPhoto(index)" aria-label="Remove photo">×</button></div></template></div><p class="fd-error" x-show="reviewErrors.photos" x-text="reviewErrors.photos"></p>
